package fable.hideseek.imba.config;
import com.google.gson.Gson;import com.google.gson.GsonBuilder;import net.fabricmc.loader.api.FabricLoader;import net.minecraft.server.world.ServerWorld;import net.minecraft.util.math.BlockPos;import net.minecraft.util.math.Box;import net.minecraft.world.World;import java.io.IOException;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.StandardCopyOption;import java.util.ArrayList;import java.util.LinkedHashSet;import java.util.List;import java.util.Set;
public final class OverlayBarrierConfig{private static final Gson GSON=new GsonBuilder().setPrettyPrinting().create();private static final Path PATH=FabricLoader.getInstance().getConfigDir().resolve("imba_overlay_barriers.json");private static final Set<Entry> ENTRIES=new LinkedHashSet<>();private OverlayBarrierConfig(){}public static void load(){ENTRIES.clear();if(!Files.exists(PATH)){save();return;}try{Data data=GSON.fromJson(Files.readString(PATH),Data.class);if(data!=null&&data.entries!=null)ENTRIES.addAll(data.entries);}catch(IOException|RuntimeException e){System.err.println("[IMBA] Не удалось загрузить накладываемые барьеры: "+e.getMessage());}}public static boolean contains(World world,BlockPos pos){return world!=null&&pos!=null&&ENTRIES.contains(Entry.of(world,pos));}public static boolean add(ServerWorld world,BlockPos pos){if(world==null||pos==null)return false;boolean changed=ENTRIES.add(Entry.of(world,pos));if(changed)save();return changed;}public static boolean remove(ServerWorld world,BlockPos pos){if(world==null||pos==null)return false;boolean changed=ENTRIES.remove(Entry.of(world,pos));if(changed)save();return changed;}public static List<Entry> snapshot(){return List.copyOf(ENTRIES);}public static List<Box> boxes(World world,Box query){if(world==null||query==null)return List.of();String id=world.getRegistryKey().getValue().toString();List<Box> result=new ArrayList<>();for(Entry entry:ENTRIES){if(!entry.world.equals(id))continue;Box box=new Box(entry.x,entry.y,entry.z,entry.x+1.0D,entry.y+1.0D,entry.z+1.0D);if(box.intersects(query))result.add(box);}return result;}public static void save(){try{Files.createDirectories(PATH.getParent());Path tmp=PATH.resolveSibling(PATH.getFileName()+".tmp");Files.writeString(tmp,GSON.toJson(new Data(new ArrayList<>(ENTRIES))));Files.move(tmp,PATH,StandardCopyOption.REPLACE_EXISTING);}catch(IOException e){System.err.println("[IMBA] Не удалось сохранить накладываемые барьеры: "+e.getMessage());}}public static final class Entry{public String world;public int x,y,z;public Entry(){}public Entry(String world,int x,int y,int z){this.world=world;this.x=x;this.y=y;this.z=z;}public static Entry of(World world,BlockPos pos){return new Entry(world.getRegistryKey().getValue().toString(),pos.getX(),pos.getY(),pos.getZ());}public BlockPos pos(){return new BlockPos(x,y,z);}@Override public boolean equals(Object o){if(this==o)return true;if(!(o instanceof Entry e))return false;return x==e.x&&y==e.y&&z==e.z&&java.util.Objects.equals(world,e.world);}@Override public int hashCode(){return java.util.Objects.hash(world,x,y,z);}}private record Data(List<Entry> entries){}
}
